#pragma once
#include "AssistantView.h"
#include "ReferenceView.h"
class SequenceCompareView final:public juce::Component,private juce::Timer {
    NovaProcessor& p;juce::Colour accent;juce::TextButton prepare{"Preparar misma secuencia"},a{"Original A"},b{"Recreado B"},stop{"Detener"},cancel{"Cancelar"};juce::ToggleButton level{"Igualar volumen A/B"};
public:
    SequenceCompareView(NovaProcessor& owner,juce::Colour c):p(owner),accent(c){for(auto* child:std::initializer_list<juce::Component*>{&prepare,&a,&b,&stop,&cancel,&level}){addAndMakeVisible(child);child->setWantsKeyboardFocus(false);}prepare.onClick=[this]{p.prepareSequenceComparison();};a.onClick=[this]{p.toggleSequenceAudition(0);};b.onClick=[this]{p.toggleSequenceAudition(1);};stop.onClick=[this]{p.stopReference();};cancel.onClick=[this]{p.cancelFit();};level.onClick=[this]{p.stopReference();p.matchLevel.store(level.getToggleState());};startTimerHz(20);}
    void setAccent(juce::Colour c){accent=c;repaint();}
    void resized()override{prepare.setBounds(18,52,240,32);a.setBounds(274,52,145,32);b.setBounds(431,52,145,32);stop.setBounds(588,52,100,32);level.setBounds(706,52,220,32);cancel.setBounds(938,52,114,32);}
    void paint(juce::Graphics& g)override{
        g.setColour(juce::Colour(0xff080f1c));g.fillRoundedRectangle(getLocalBounds().toFloat(),18);nova::glass::panel(g,getLocalBounds().toFloat(),accent,18,this);g.setColour(juce::Colour(0xb0080f1c));g.fillRoundedRectangle(getLocalBounds().toFloat().reduced(1),17);g.setColour(juce::Colours::white);g.setFont(20);g.drawText("COMPARAR / MISMAS NOTAS Y DURACIONES",18,10,getWidth()-36,30,juce::Justification::centredLeft);
        auto view=p.sequenceView();if(!view){g.setFont(15*p.textScale());g.setColour(juce::Colour(0xffbacbdd));g.drawFittedText(p.comparisonPreparing()?"Preparando la secuencia... "+juce::String(static_cast<int>(p.fitProgress.load()*100))+" %":"Revisa el fragmento en Aprender y prepara la comparacion.\nA conserva la interpretacion original. B toca la secuencia monofonica detectada con el instrumento actual.\nSi cambias el instrumento, las referencias o el volumen igualado, prepara otra vez.",18,130,getWidth()-36,200,juce::Justification::centred,5);return;}
        float maximum=.001f;for(float x:view->waveA)maximum=std::max(maximum,x);for(float x:view->waveB)maximum=std::max(maximum,x);
        auto draw=[&](juce::Rectangle<float> area,const auto& values,const juce::String& name,juce::Colour colour){g.setColour(juce::Colour(0xff111e2e));g.fillRoundedRectangle(area,12);g.setColour(colour);g.setFont(14*p.textScale());g.drawText(name,area.reduced(12).removeFromTop(25),juce::Justification::centredLeft);for(int i=0;i<256;++i){float x=area.getX()+12+i*(area.getWidth()-24)/255,h=values[i]/maximum*(area.getHeight()-54)*.5f;g.drawVerticalLine(static_cast<int>(x),area.getCentreY()+12-h,area.getCentreY()+12+h);}};
        draw({18,101,508,182},view->waveA,"A / ORIGINAL",juce::Colour(0xffb0bfd1));draw({544,101,508,182},view->waveB,"B / SINTESIS",accent);
        auto report=p.reviewView();if(report){auto area=juce::Rectangle<float>(18,315,1034,70);g.setColour(juce::Colour(0xff111c2b));g.fillRoundedRectangle(area,10);double duration=std::max(.001,report->analysis.duration);for(const auto& n:report->analysis.sequence){float x=area.getX()+static_cast<float>(n.range.start/duration)*area.getWidth(),width=static_cast<float>(n.range.length()/duration)*area.getWidth(),y=area.getBottom()-8-(n.note-24)/84.f*(area.getHeight()-16);g.setColour(accent.withAlpha(.8f));g.fillRoundedRectangle(x,y,std::max(2.f,width-1),4,2);}double pos=p.referencePosition()-p.selectedRange().start;if(pos>=0&&pos<=duration){g.setColour(juce::Colours::white);g.drawVerticalLine(static_cast<int>(area.getX()+pos/duration*area.getWidth()),area.getY(),area.getBottom());}}
        g.setFont(13*p.textScale());g.setColour(juce::Colour(0xffc6d4e4));g.drawText(juce::String(view->events)+" eventos detectados / ARP omitido / intensidades estimadas / cada escucha empieza al inicio",18,286,1034,24,juce::Justification::centredLeft);
        g.drawText("Ataque: "+juce::String(view->attack,4)+"   Cuerpo: "+juce::String(view->body,4)+"   Envolvente: "+juce::String(view->envelope,4),18,399,730,25,juce::Justification::centredLeft);g.drawText(view->pitchMeasured?"Error tonal max.: "+juce::String(view->maxPitchCents,1)+" c":"Afinacion sin medicion fiable",755,399,297,25,juce::Justification::centredRight);g.setFont(12*p.textScale());g.setColour(juce::Colour(0xff98acc3));g.drawText("Distancias de hasta 8 eventos; menor es mejor. No son porcentajes ni transcripcion polifonica.",18,437,1034,24,juce::Justification::centredLeft);
    }
private:
    void timerCallback()override{if(!isShowing())return;bool busy=p.loading.load()||p.fitting.load();auto view=p.sequenceView();prepare.setEnabled(!busy&&p.reviewView()!=nullptr);a.setEnabled(!busy&&view!=nullptr);b.setEnabled(!busy&&view!=nullptr);level.setEnabled(!busy);cancel.setEnabled(busy);level.setToggleState(p.matchLevel.load(),juce::dontSendNotification);a.setToggleState(p.referencePlaying()&&p.previewMode.load()==4,juce::dontSendNotification);b.setToggleState(p.referencePlaying()&&p.previewMode.load()==5,juce::dontSendNotification);if(!view&&p.previewMode.load()>=4&&p.referencePlaying())p.stopReference();repaint();}
};
class PatchVersionsView final:public juce::Component,private juce::Timer {
    NovaProcessor& p;juce::Colour accent;juce::ComboBox versions;juce::TextEditor name;juce::TextButton save{"Guardar version"},restore{"Restaurar elegida"},undo{"Deshacer ajuste"};juce::StringArray last;
public:
    PatchVersionsView(NovaProcessor& owner,juce::Colour c):p(owner),accent(c){for(auto* child:std::initializer_list<juce::Component*>{&versions,&name,&save,&restore,&undo})addAndMakeVisible(child);name.setTextToShowWhenEmpty("Nombre, por ejemplo: ataque suave",juce::Colour(0xff8193aa));name.setInputRestrictions(64);save.onClick=[this]{p.saveVersion(name.getText());};restore.onClick=[this]{p.restoreVersion(versions.getSelectedItemIndex());};undo.onClick=[this]{p.undoFit();};versions.setTextWhenNothingSelected("Todavia no hay versiones");for(auto* c:std::initializer_list<juce::Component*>{&versions,&save,&restore,&undo})c->setWantsKeyboardFocus(false);startTimerHz(10);}
    void setAccent(juce::Colour c){accent=c;repaint();}
    void resized()override{versions.setBounds(30,88,700,36);restore.setBounds(750,88,280,36);name.setBounds(30,150,700,36);save.setBounds(750,150,280,36);undo.setBounds(750,213,280,32);}
    void paint(juce::Graphics& g)override{g.setColour(juce::Colour(0xff080f1c));g.fillRoundedRectangle(getLocalBounds().toFloat(),18);nova::glass::panel(g,getLocalBounds().toFloat(),accent,18,this);g.setColour(juce::Colour(0xb0080f1c));g.fillRoundedRectangle(getLocalBounds().toFloat().reduced(1),17);g.setColour(juce::Colours::white);g.setFont(21);g.drawText("VERSIONES DEL INSTRUMENTO",30,20,getWidth()-60,35,juce::Justification::centredLeft);g.setFont(15*p.textScale());g.setColour(accent);g.drawText(juce::String(last.size())+" / 12 versiones guardadas con el proyecto y el preset",30,213,690,32,juce::Justification::centredLeft);g.setColour(juce::Colour(0xffbacadd));g.drawFittedText("Cada recreacion y refinamiento aceptado guarda una version automaticamente.\nTambien puedes guardar un ajuste manual con nombre.\n\nAl restaurar se recuperan controles, modelos sintetizados, banco y arpegiador.\nLas referencias originales y las comparaciones no se guardan como audio.\n\nAl llegar a doce versiones se reemplaza la mas antigua. Abrir otro preset carga su propio historial.",30,273,getWidth()-60,150,juce::Justification::topLeft,9);g.setFont(12*p.textScale());g.setColour(accent);g.drawText(p.status(),30,444,getWidth()-60,22,juce::Justification::centredLeft);}
private:
    void timerCallback()override{if(!isShowing())return;auto now=p.versionNames();if(now!=last){versions.clear(juce::dontSendNotification);versions.addItemList(now,1);if(!now.isEmpty())versions.setSelectedId(now.size(),juce::dontSendNotification);last=now;}bool busy=p.loading.load()||p.fitting.load();save.setEnabled(!busy);restore.setEnabled(!busy&&versions.getSelectedId()>0);versions.setEnabled(!busy);undo.setEnabled(!busy&&p.canUndoFit());name.setFont(juce::Font(14*p.textScale()));repaint();}
};
class RecreateWorkspace final:public juce::Component,private juce::Timer {
    NovaProcessor& p;ReferenceView reference;AssistantView learn;SequenceCompareView compare;PatchVersionsView versions;std::array<juce::TextButton,4> tabs;juce::TextButton cancelTask{"Cancelar tarea"};int page=0;
public:
    std::function<void()> onClose;
    RecreateWorkspace(NovaProcessor& owner,juce::Colour c):p(owner),reference(owner),learn(owner,c),compare(owner,c),versions(owner,c){for(auto* child:std::initializer_list<juce::Component*>{&reference,&learn,&compare,&versions})addChildComponent(child);const char* names[]={"Muestra y recorte","Aprender","Comparar A/B","Versiones"};for(int i=0;i<4;++i){addAndMakeVisible(tabs[i]);tabs[i].setButtonText(names[i]);tabs[i].setWantsKeyboardFocus(false);tabs[i].onClick=[this,i]{showPage(i);};}addAndMakeVisible(cancelTask);cancelTask.setWantsKeyboardFocus(false);cancelTask.onClick=[this]{p.cancelFit();};learn.onClose=[this]{showPage(0);};setAccent(c);showPage(0);startTimerHz(20);}
    void setAccent(juce::Colour c){reference.accent=c;learn.setAccent(c);compare.setAccent(c);versions.setAccent(c);repaint();}
    void showPage(int id){p.stopReference();page=std::clamp(id,0,3);juce::Component* children[]={&reference,&learn,&compare,&versions};for(int i=0;i<4;++i){children[i]->setVisible(i==page);tabs[i].setToggleState(i==page,juce::dontSendNotification);}if(auto* editor=findParentComponentOfClass<juce::AudioProcessorEditor>())editor->grabKeyboardFocus();}
    int currentPage()const{return page;}
    void auditionSelected(int mode){if(page==0)p.toggleReference();else if(page==1)learn.auditionSelected(mode);else if(page==2)p.toggleSequenceAudition(p.previewMode.load()==5?1:0);}
    void resized()override{for(int i=0;i<4;++i)tabs[i].setBounds(i*230,0,218,30);cancelTask.setBounds(942,0,130,30);for(auto* c:std::initializer_list<juce::Component*>{&reference,&learn,&compare,&versions})c->setBounds(0,40,getWidth(),getHeight()-40);}
private:
    void timerCallback()override{if(!isShowing())return;cancelTask.setEnabled(p.fitting.load()||p.loading.load());reference.refresh();reference.setEnabled(!p.fitting.load()&&!p.loading.load());}
};
